<script type="text/javascript">
var id = {CHAT_ID};
var group = {GROUP_ID};  
var lastgroup = {GROUP_ID};  

$('select[name="group_chat"]').change(function (){
    lastgroup = group;
    group = $(this).val();
    get_message_chat(0);
    $('span.activeEditChat').removeClass('activeEditChat').hide();
});  

ajax.callback.chat = function(data) {
    if(data.up) $('#chat').scrollTop(0);

    if(data.clear) {
        $('.chat_message').attr('value', '');
        get_message_chat(1);
    }
    else if(data.del) {
        for(i=0; i < data.del.length; i++) {
            $('#pp_'+ data.del[i]).hide();
        }
    }else if(data.html){
        $('#pp_'+ data.post_id).show().html(data.html);
        initPostBBCode('#pp_'+ data.post_id);
        $('#pe_'+ data.post_id).hide();
        ajax.open = false;
    } else if(data.text){
        ajax.open = data.post_id;
        $('#pe_'+ data.post_id).html(data.text);
    }
    else {
        if(data.message) $('#chat').prepend(data.message);
    }

    if(data.insert) {
        $('span.activeEditChat').removeClass('activeEditChat').hide();
        ajax.open = false;
        initPostBBCode('#pp_'+ data.post_id);
    }

    if(data.update) {
        $('#chat').html(data.message);
        initPostBBCode('#chat');
    }
    if(data.id) id = data.id;
    if(data.group) group = data.group;
    if(data.lastgroup) lastgroup = data.lastgroup;  
};
setInterval(function(){ get_message_chat(0); }, 25000);

function get_message_chat(up){
    ajax.exec({action : 'chat', mode: 'select', id: id, group: group, lastgroup: lastgroup, up: up});
}
function submit_click(e) {
    e = e || window.event;
    if (e.keyCode == 13 && e.ctrlKey) {
        submit_chat();
    };
}
function submit_chat(){
    var message = $('.chat_message').val();
    if (message.length < 3) {
        alert('Вы должны ввести текст сообщения');
        $('.chat_message').focus();
        return false;
    }
    ajax.exec({action : 'chat', mode: 'insert', group: group, lastgroup: lastgroup, message: message});
}
function add_nick(text){
    var message = $('.chat_message').val();
    $('.chat_message').attr('value', message + text +' ');
    $('.chat_message').focus();
}
ajax.open = false;
function edit_comment (post_id, text, type) {
    if(ajax.open && ajax.open != post_id) {
        alert('У вас уже открыто одно быстрое редактирование!');
    } else{
        if(ajax.open && !text){
            $('#pp_'+ post_id).show();
            $('#pe_'+ post_id).hide().removeClass('activeEditChat');
        } else{
            $('#pp_'+ post_id).hide();
            $('#pe_'+ post_id).show().addClass('activeEditChat');

            ajax.exec({
                action  : 'chat',
                mode    : 'edit',
                post_id : post_id,
                text    : text,
                group    : group,
                lastgroup: lastgroup,
                type    : type
            });
        }
        ajax.open = false;
    }
}
function del_message_chat(){
    if(!confirm('Вы уверены, что хотите удалить эти сообщения?')) return false;
    var ids = 0;
    $('input.chat-post:checked').each(function(){
        ids += ','+ this.value;
    });
    if(!ids) alert('Вы не выбрали сообщения.');
    else ajax.exec({action : 'chat', mode: 'delete', group: group, ids: ids});
}
function set_hid_chbox(id)
{
    $('#pp_'+ id).toggleClass('hl-selected-post');
    return false;
}
</script>
